package dev.jobflow.service;
import java.time.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class RateLimitService {private final JdbcTemplate jdbc; private final int limit; public RateLimitService(JdbcTemplate j,@Value("${jobflow.rate-limit.submissions-per-minute}")int l){jdbc=j;limit=l;} @Transactional public void check(String subject){Instant w=Instant.now().truncatedTo(java.time.temporal.ChronoUnit.MINUTES);Integer count=jdbc.queryForObject("INSERT INTO rate_limit_buckets(subject, window_start, request_count) VALUES (?, ?, 1) ON CONFLICT (subject, window_start) DO UPDATE SET request_count = rate_limit_buckets.request_count + 1 RETURNING request_count",Integer.class,subject,w);if(count==null||count>limit)throw new RateLimitExceededException();} public static class RateLimitExceededException extends RuntimeException{public RateLimitExceededException(){super("Submission rate limit exceeded");}}}
